"""Private card collection and owner-scoped reuse, without checkout text parsing.

Legacy native purchases remain readable/reconcilable through the existing code.
New purchases use opaque Kernel credential handles, never card readback.
"""
import hmac
import json
import secrets

from .payments import Payments as LegacyPayments
from .store import AccessError

CARD_FIELDS = {'number': 'Card number', 'expiration': 'Expiry (MM/YY)',
               'exp_month': 'Expiry month (MM)', 'exp_year': 'Expiry year (YYYY)',
               'cvc': 'Security code', 'billing_name': 'Name on card'}


class Payments(LegacyPayments):
    def __init__(self, service):
        super().__init__(service)
        with service.store.connection() as db:
            db.execute('''CREATE TABLE IF NOT EXISTS private_payment_cards (
                team TEXT NOT NULL, owner TEXT NOT NULL, vault TEXT NOT NULL,
                item_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL,
                PRIMARY KEY(team,owner))''')

    def inventory(self, turn):
        self.service.assert_private(turn)
        with self.service.store.connection() as db:
            row = db.execute("SELECT state FROM private_payment_cards WHERE team=? AND owner=?",
                             (turn.source.scope_id, turn.source.user_id)).fetchone()
        return {'provider': 'kernel', 'saved': bool(row and row['state'] == 'active')}

    async def request(self, turn, *, merchant_name, amount, pay_button_selector,
                      card_fields=None, merchant_country='IN'):
        """Call only for the owner's current instruction to proceed with payment."""
        self.service.assert_private(turn)
        self.service.delegations.check_execution(turn)
        if (not isinstance(merchant_name, str) or not merchant_name.strip() or len(merchant_name) > 120
                or type(amount) is not int or amount <= 0 or merchant_country != 'IN'):
            raise AccessError('Provide the merchant and positive INR amount in paise.', 400)
        if not isinstance(pay_button_selector, str) or not 0 < len(pay_button_selector) <= 4096:
            raise AccessError('Select the final payment button.', 400)
        names = card_fields if card_fields is not None else ['number', 'expiration', 'cvc', 'billing_name']
        if (not isinstance(names, list) or not names or any(not isinstance(n, str) or n not in CARD_FIELDS for n in names)
                or len(set(names)) != len(names) or 'number' not in names
                or not ('expiration' in names or {'exp_month', 'exp_year'} <= set(names))):
            raise AccessError('Specify the card fields needed by this checkout.', 400)
        with self.service.lock_for(turn.home):
            plan = self.service.kernel_vault.inspect(turn)
            with self.service.store.connection() as db:
                unresolved = db.execute("SELECT r.id FROM requests r JOIN kernel_purchases p ON r.id=p.request_id WHERE r.team=? AND r.owner=? AND p.state NOT IN ('completed','cancelled','review') LIMIT 1",
                    (turn.source.scope_id, turn.source.user_id)).fetchone()
                saved = db.execute('SELECT * FROM private_payment_cards WHERE team=? AND owner=?',
                    (turn.source.scope_id, turn.source.user_id)).fetchone()
            if unresolved:
                raise AccessError('Reconcile the existing payment before starting another.', 409)
            if saved and saved['state'] != 'active':
                raise AccessError('Previous card removal needs reconciliation.', 409)
            vault = self.service.kernel_vault.ensure_vault(turn.source.scope_id, turn.source.user_id)['id']
            saved_item = self.service.kernel_vault.client.get_credential(saved['vault'], saved['item_key']) if saved else None
            if saved and (not saved_item or saved_item['state']['status'] != 'ready'):
                raise AccessError('The remembered card is unavailable. Reconnect it privately.', 409)
            if saved_item and not set(names) <= {f['name'] for f in saved_item['spec']['fields']}:
                raise AccessError('The remembered card does not contain the fields this checkout needs.', 409)
            checkout = dict(flow='private_card', merchant_name=merchant_name.strip(), amount=amount,
                currency='inr', merchant_country='IN', origin=plan.origin, page_url=plan.page_url,
                browser_id=plan.browser_id, pay_button_selector=pay_button_selector,
                pay_label=self._button(turn, plan, pay_button_selector), card_fields=names)
            row = self.service.store.create(team=turn.source.scope_id, owner=turn.source.user_id,
                home=self.service.private_home(turn.source.scope_id, turn.source.user_id), task_id=turn.task_id,
                source=turn.source.to_dict(), task=turn.message, kind='payment',
                label=f'{merchant_name.strip()} · Pay ₹{amount / 100:.2f}', origin=plan.origin,
                checkout=checkout, gateway_event_id=turn.message_id)
            key = saved['item_key'] if saved else 'private-card-' + secrets.token_hex(16)
            with self.service.store.connection() as db:
                db.execute('INSERT OR IGNORE INTO kernel_purchases VALUES (?,?,?,?,?,?,?,?,NULL)',
                    (row['id'], saved['vault'] if saved else vault, key, 'purchase-' + row['id'],
                     'ready' if saved else 'review', 1 if saved else None,
                     self.service.store.clock() if saved else None, None))
                if saved:
                    db.execute("UPDATE requests SET status='resumed',resume_delivered=? WHERE id=?",
                               (self.service.store.clock(), row['id']))
            if saved:
                return dict(payment_id=row['id'], status='ready', state='ready', remembered=True)
        delivery = await self.service.deliver_link(row)
        return dict(delivery, status='waiting_for_owner', payment_id=row['id'],
                    link_delivery=delivery.get('status', 'unconfirmed'))

    def _observe(self, turn, checkout=None, **kwargs):
        if not checkout or checkout.get('flow') != 'private_card':
            return super()._observe(turn, checkout, **kwargs)
        plan = self.service.kernel_vault.inspect(turn, checkout['origin'])
        if plan.page_url != checkout['page_url'] or plan.browser_id != checkout['browser_id']:
            raise AccessError('The payment page or browser changed.', 409)
        return plan, checkout['amount'], ''

    def view(self, request_id, token, identity):
        if not isinstance(token, str) or not hmac.compare_digest(token, self.service.store.token(request_id)):
            raise AccessError('This payment link is invalid.', 404)
        row, purchase, checkout = self._row(request_id, identity=identity)
        if checkout.get('flow') != 'private_card' or purchase['state'] in {'creating_otp', 'otp', 'otp_ready'}:
            return super().view(request_id, token, identity)
        result = dict(provider='kernel_payment', payment_id=request_id, state=purchase['state'],
                      merchant=checkout['merchant_name'], amount=checkout['amount'], currency='inr')
        if purchase['state'] in {'enrollment', 'creating_wallet'}:
            item = self.service.kernel_vault.client.get_credential(purchase['vault'], purchase['wallet_key'])
            if item and item['state']['status'] == 'pending_collection':
                item = self.service.kernel_vault.client.collect(purchase['vault'], purchase['wallet_key'])
                if item.get('action'):
                    result['collection_url'] = item['action']['url']
        return result

    def _drive(self, row, purchase):
        checkout = json.loads(row['checkout'])
        if checkout.get('flow') != 'private_card' or purchase['state'] in {'creating_otp', 'otp'}:
            return super()._drive(row, purchase)
        pid, vault, key = row['id'], purchase['vault'], purchase['wallet_key']
        state = purchase['state']
        client = self.service.kernel_vault.client
        if state == 'approved':
            self._claim(pid, 'approved', 'creating_wallet')
            definitions = [dict(name=n, label=CARD_FIELDS[n], type='password', required=True, sensitive=True)
                           for n in checkout['card_fields']]
            client.create_credential(vault, key, definitions, description='Payment card')
            self._state(pid, 'enrollment')
            state = 'enrollment'
        if state not in {'creating_wallet', 'enrollment'}:
            return
        item = client.get_credential(vault, key)
        if not item:
            return  # Never replay an uncertain creation.
        if item['state']['status'] != 'ready':
            self._state(pid, 'enrollment')
            return
        with self.service.store.connection() as db:
            if purchase['remember']:
                db.execute('INSERT INTO private_payment_cards VALUES (?,?,?,?,?)',
                           (row['team'], row['owner'], vault, key, 'active'))
            db.execute("UPDATE kernel_purchases SET state='ready' WHERE request_id=?", (pid,))
            db.execute("UPDATE requests SET status='saved' WHERE id=? AND status='waiting'", (pid,))

    def fill(self, turn, *, payment_id, fields):
        row, purchase, checkout = self._row(payment_id, turn=turn)
        if checkout.get('flow') != 'private_card':
            return super().fill(turn, payment_id=payment_id, fields=fields)
        if (not isinstance(fields, list) or not fields or
                any(not isinstance(f, dict) or set(f) != {'field', 'selector'} or f['field'] not in checkout['card_fields']
                    or not isinstance(f['selector'], str) or not 0 < len(f['selector']) <= 4096 for f in fields)
                or len({f['field'] for f in fields}) != len(fields)
                or len({f['selector'] for f in fields}) != len(fields)):
            raise AccessError('Bind the collected card fields to checkout controls.', 400)
        with self.service.lock_for(turn.home):
            if row['expires'] <= self.service.store.clock():
                raise AccessError('Payment request expired.', 410)
            plan, _, _ = self._observe(turn, checkout)
            self._claim(payment_id, 'ready', 'filling')
            self.service.kernel_vault._arm_privacy(turn, plan, fields, sensitive=True)
            result = self.service.kernel_vault.client.fill(purchase['vault'], purchase['wallet_key'],
                browser_id=plan.browser_id, page_url=plan.page_url, fields=fields)
            self.service.kernel_vault.refresh_privacy(turn)
            state = 'filled' if result['status'] == 'completed' else 'fill_' + result['status']
            self._state(payment_id, state)
            return dict(payment_id=payment_id, state=state)

    def submit(self, turn, *, payment_id):
        from tools import browser_vault_tool as native
        row, purchase, checkout = self._row(payment_id, turn=turn)
        if checkout.get('flow') != 'private_card':
            return super().submit(turn, payment_id=payment_id)
        with self.service.lock_for(turn.home):
            if row['expires'] <= self.service.store.clock():
                raise AccessError('Payment request expired.', 410)
            plan, _, _ = self._observe(turn, checkout)
            self._claim(payment_id, 'filled', 'submitting')
            with self.service.store.connection() as db:
                db.execute('UPDATE kernel_purchases SET submitted=? WHERE request_id=?', (self.service.store.clock(), payment_id))
            expression = '''(() => {if(location.href!==URL_VALUE||window.__hermesNativePageBinding!==MARKER_VALUE)return false;
              const buttons=document.querySelectorAll(SELECTOR_VALUE);if(buttons.length!==1)return false;
              const b=buttons[0];if(!b.getClientRects().length||b.disabled)return false;
              if(b.tagName!=='BUTTON'&&!(b.tagName==='INPUT'&&b.type==='submit'))return false;
              const label=b.tagName==='BUTTON'?b.innerText:b.value;if(label.trim()!==LABEL_VALUE)return false;
              b.click();return true;})()'''
            for name, value in [('URL_VALUE', plan.page_url), ('MARKER_VALUE', plan.marker),
                                ('SELECTOR_VALUE', checkout['pay_button_selector']), ('LABEL_VALUE', checkout['pay_label'])]:
                expression = expression.replace(name, json.dumps(value))
            response = native._eval_js(plan.task_id, expression)
            if response.get('success') and response.get('result') is False:
                self._state(payment_id, 'submit_blocked')
            else:
                self._state(payment_id, 'submitted_unknown')
            return dict(payment_id=payment_id, state=self._row(payment_id, turn=turn)[1]['state'],
                        next='Check the merchant outcome or bank verification. Never repeat an uncertain payment.')

    def complete(self, turn, *, payment_id, outcome):
        """Agent reports the merchant outcome after observing the browser."""
        with self.service.lock_for(turn.home):
            row, purchase, checkout = self._row(payment_id, turn=turn)
            if checkout.get('flow') != 'private_card':
                raise AccessError('Use the legacy reconciliation path for this existing purchase.', 409)
            if outcome not in {'paid', 'failed'} or purchase['state'] not in {'submitted_unknown', 'otp_submitted_unknown'}:
                raise AccessError('Confirm the merchant outcome of the submitted payment first.', 409)
            plan = self.service.kernel_vault.inspect(turn, checkout['origin'])
            if plan.browser_id != checkout['browser_id']:
                raise AccessError('Payment browser changed.', 403)
            # Remove filled controls, including frames, before lifting privacy guards.
            self.service.cloud_browser.stop(turn)
            self._state(payment_id, 'completed')
            pending = False
            if not purchase['remember']:
                try:
                    self._remove_wallet(row, purchase)
                except Exception:
                    pending = True
            return dict(payment_id=payment_id, state='completed', outcome=outcome, card_removal_pending=pending)

    def _remove_wallet(self, row, purchase):
        checkout = json.loads(row['checkout'])
        if checkout.get('flow') != 'private_card':
            return super()._remove_wallet(row, purchase)
        with self.service.store.connection() as db:
            db.execute('INSERT OR REPLACE INTO private_payment_cards VALUES (?,?,?,?,?)',
                       (row['team'], row['owner'], purchase['vault'], purchase['wallet_key'], 'removal_pending'))
        self.service.kernel_vault.client.delete_credential(purchase['vault'], purchase['wallet_key'])
        with self.service.store.connection() as db:
            db.execute("DELETE FROM private_payment_cards WHERE team=? AND owner=? AND item_key=? AND state='removal_pending'",
                       (row['team'], row['owner'], purchase['wallet_key']))

    def cleanup(self):
        super().cleanup()
        with self.service.store.connection() as db:
            rows = [dict(r) for r in db.execute("SELECT r.* FROM requests r JOIN kernel_purchases p ON p.request_id=r.id JOIN private_payment_cards c ON c.item_key=p.wallet_key WHERE c.state='removal_pending' AND p.state IN ('completed','cancelled') AND p.remember=0")]
        for row in rows:
            try:
                with self.service.lock_for(self.service.private_home(row['team'], row['owner'])):
                    _, purchase, _ = self._row(row['id'], identity=dict(team=row['team'], owner=row['owner']))
                    self._remove_wallet(row, purchase)
            except Exception:
                continue

    def cancel(self, turn, *, payment_id):
        row, purchase, checkout = self._row(payment_id, turn=turn)
        if checkout.get('flow') != 'private_card':
            return super().cancel(turn, payment_id=payment_id)
        with self.service.lock_for(turn.home):
            if purchase['submitted'] is not None:
                raise AccessError('Reconcile this submitted payment; cancellation is not a refund.', 409)
            self._claim(payment_id, purchase['state'], 'cancelling')
            self.service.cloud_browser.stop(turn)
            if not purchase['remember']:
                self._remove_wallet(row, purchase)
            self._state(payment_id, 'cancelled')
            with self.service.store.connection() as db:
                db.execute("UPDATE requests SET status='cancelled' WHERE id=?", (payment_id,))
            return dict(payment_id=payment_id, state='cancelled')
